/*
 * test_icon_theme.c — headless icon-theme engine suite
 *
 * Pins src/theme/icon_theme.c (the freedesktop icon-theme engine)
 * against a synthetic, fully-controlled fixture tree: a theme with
 * an inheritance chain, a threshold directory, scale!=1 entries,
 * SVG decoys, a pixmaps fallback, and deliberately-missing names.
 * Every fixture icon is a SOLID-COLOR PNG (tests/test_icon_pngs.h,
 * generated by the Python snippet below) so assertions can check
 * not just that a path resolved but WHICH icon a surface decoded —
 * color is identity.
 *
 * Fixture regeneration (Python 3, Pillow not required — plain
 * zlib/struct):
 *
 *   import struct, zlib
 *   def png(w, h, rgb):
 *       raw = b''.join(b'\x00' + bytes([*rgb, 255]) * w for _ in range(h))
 *       def ch(tag, data):
 *           c = struct.pack('>I', len(data)) + tag + data
 *           return c + struct.pack('>I', zlib.crc32(tag + data) & 0xffffffff)
 *       ihdr = struct.pack('>IIBBBBB', w, h, 8, 6, 0, 0, 0)
 *       return b'\x89PNG\r\n\x1a\n' + ch(b'IHDR', ihdr) + \
 *              ch(b'IDAT', zlib.compress(raw)) + ch(b'IEND', b'')
 *
 * Covered, group by group:
 *
 *   name detection  — env override > XSETTINGS live > user gtk ini >
 *                     xfconf xsettings.xml > kdeglobals > icon-theme
 *                     file > system gtk ini > default/index.theme >
 *                     hicolor; hostile names rejected; XML entities
 *                     unescaped (the XSETTINGS channel itself is
 *                     exercised live in the X11 integration suite)
 *   lookup          — exact size, inheritance, hicolor terminal,
 *                     relaxed closest-size, scale!=1 skipped,
 *                     SVG never offered, pixmaps last resort
 *   caching         — positive + negative hits, reset drops both
 *   surfaces        — decode + borrow + symbolic tint (pixel proof)
 *   classification  — extension table (case-insensitive), the
 *                     executable-bit stat for extension-less files,
 *                     the place chains
 *
 * Runs headless (no display) — the GUI pixel proof lives in the X11
 * integration suite's file-dialog group.
 */

#include "fdk/fdk.h"
#include "core/alloc_internal.h"
#include "theme/theme_internal.h"

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>

#ifndef _DEFAULT_SOURCE
#define _DEFAULT_SOURCE
#endif
#include <unistd.h>

#include "test_icon_pngs.h"

static int failures = 0;

#define CHECK(cond, name)                                                  \
    do {                                                                   \
        if (!(cond)) {                                                     \
            fprintf(stderr, "FAIL: %s (line %d)\n", name, __LINE__);       \
            failures++;                                                    \
        }                                                                  \
    } while (0)

/* ---- fixture scaffolding -------------------------------------------- */

static char g_root[512]; /* the scratch root, removed on exit */

static void write_file(const char *path, const void *data, size_t len) {
    FILE *f = fopen(path, "wb");
    if (f == NULL) {
        perror(path);
        exit(2);
    }
    if (len > 0 && fwrite(data, 1, len, f) != len) {
        perror("fwrite");
        exit(2);
    }
    fclose(f);
}

static void mkdir_p(const char *path) {
    if (mkdir(path, 0755) == 0 || errno == EEXIST) {
        return;
    }
    /* Create parents, then retry. */
    char buf[600];
    snprintf(buf, sizeof(buf), "%s", path);
    for (char *slash = buf + 1; *slash != '\0'; slash++) {
        if (*slash == '/') {
            *slash = '\0';
            (void)mkdir(buf, 0755);
            *slash = '/';
        }
    }
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        perror(path);
        exit(2);
    }
}

static void fixture_dir(const char *rel) {
    char buf[600];
    snprintf(buf, sizeof(buf), "%s/%s", g_root, rel);
    mkdir_p(buf);
}

static void fixture_png(const char *rel, const unsigned char *data,
                        size_t len) {
    char buf[600];
    snprintf(buf, sizeof(buf), "%s/%s", g_root, rel);
    write_file(buf, data, len);
}

static void fixture_text(const char *rel, const char *content) {
    char buf[600];
    snprintf(buf, sizeof(buf), "%s/%s", g_root, rel);
    write_file(buf, content, strlen(content));
}

/* Point the engine's whole world at the fixture tree: XDG_DATA_HOME
 * carries the icons, XDG_CONFIG_HOME carries the settings files, and
 * every other discovery input is scrubbed. */
static void env_point_at_fixture(void) {
    char buf[600];
    snprintf(buf, sizeof(buf), "%s/data", g_root);
    setenv("XDG_DATA_HOME", buf, 1);
    snprintf(buf, sizeof(buf), "%s/config", g_root);
    setenv("XDG_CONFIG_HOME", buf, 1);
    snprintf(buf, sizeof(buf), "%s/datadirs", g_root);
    setenv("XDG_DATA_DIRS", buf, 1);
    /* The SYSTEM config roots get a scratch dir too: unset, the
     * system-gtk channel would read the host's real /etc/xdg (not
     * hermetic); and unset DISPLAY keeps a live desktop's XSETTINGS
     * daemon (channel 2) out of these file-channel tests when the
     * suite happens to run from inside a session. */
    snprintf(buf, sizeof(buf), "%s/sysxdg", g_root);
    setenv("XDG_CONFIG_DIRS", buf, 1);
    unsetenv("DISPLAY");
    unsetenv("FDK_ICON_THEME");
    unsetenv("XDG_ICON_THEME");
    fdk__icon_theme_reset();
}

/* Builds:
 *
 *   <root>/data/icons/
 *     fdktest/            (Inherits=fdkparent)
 *       index.theme
 *       16x16/   Fixed 16   folder (.png + green .svg contest),
 *                            text-x-generic, image-x-generic,
 *                            run-symbolic
 *       48x48/   Fixed 48   folder, image-x-generic,
 *                            shadow-test.svg (EMPTY — refusal fixture)
 *       32x32/   Scalable 16..64  audio-x-generic
 *       64x64@2/ Fixed 64 Scale=2  video-x-generic   (must be skipped)
 *       24x24/   Threshold 24   (only the empty application-zip.svg
 *                               decoy)
 *       svgonly/ Scalable 8..512  image-x-preview.svg (solid RED,
 *                               rasterized through nanosvg) +
 *                               class-*.svg (CSS <style>+class= —
 *                               the modern-theme shape, incl. the
 *                               trailing-whitespace properties text
 *                               that overflowed the parser's heap)
 *     fdkparent/          (Inherits=hicolor)
 *       index.theme
 *       48x48/   Fixed 48   package-x-generic, shadow-test.png
 *     hicolor/
 *       index.theme        (no Inherits — the terminal)
 *       16x16/   Fixed 16   text-x-generic   (the inherited last hit)
 *   <root>/config/         (empty until a detection test fills it)
 *   <root>/datadirs/icons/default/  written by the detection test
 *                               (the system-default channel)
 *   <root>/sysxdg/          the system XDG_CONFIG_DIRS root (the
 *                               system-gtk channel's fixture)
 */
static void build_fixture(void) {
    static char tmpl[] = "/tmp/fdk-itheme-XXXXXX";
    char *d = mkdtemp(tmpl);
    if (d == NULL) {
        perror("mkdtemp");
        exit(2);
    }
    snprintf(g_root, sizeof(g_root), "%s", d);

    fixture_dir("data/icons/fdktest/16x16");
    fixture_dir("data/icons/fdktest/24x24");
    fixture_dir("data/icons/fdktest/32x32");
    fixture_dir("data/icons/fdktest/48x48");
    fixture_dir("data/icons/fdktest/64x64@2");
    fixture_dir("data/icons/fdktest/svgonly");
    fixture_dir("data/icons/fdkparent/48x48");
    fixture_dir("data/icons/hicolor/16x16");
    fixture_dir("config");
    fixture_dir("datadirs/pixmaps");
    fixture_dir("datadirs/icons/default");

    fixture_text("data/icons/fdktest/index.theme",
                 "[Icon Theme]\n"
                 "Name=FDK Test\n"
                 "Inherits=fdkparent\n"
                 "Directories=16x16,24x24,32x32,48x48,64x64@2,svgonly\n"
                 "\n"
                 "[16x16]\nSize=16\nType=Fixed\n"
                 "\n"
                 "[24x24]\nSize=24\nType=Threshold\nThreshold=2\n"
                 "\n"
                 "[32x32]\nSize=32\nType=Scalable\nMinSize=16\n"
                 "MaxSize=64\n"
                 "\n"
                 "[48x48]\nSize=48\nType=Fixed\n"
                 "\n"
                 "[64x64@2]\nSize=64\nType=Fixed\nScale=2\n"
                 "\n"
                 "[svgonly]\nSize=128\nType=Scalable\nMinSize=8\n"
                 "MaxSize=512\n");

    fixture_text("data/icons/fdkparent/index.theme",
                 "[Icon Theme]\n"
                 "Name=FDK Parent\n"
                 "Inherits=hicolor\n"
                 "Directories=48x48\n"
                 "\n"
                 "[48x48]\nSize=48\nType=Fixed\n");

    fixture_text("data/icons/hicolor/index.theme",
                 "[Icon Theme]\n"
                 "Name=Hicolor\n"
                 "Directories=16x16\n"
                 "\n"
                 "[16x16]\nSize=16\nType=Fixed\n");

    /* The theme's own 16-px set. */
    fixture_png("data/icons/fdktest/16x16/folder.png",
                icon_png_folder_16, icon_png_folder_16_LEN);
    fixture_png("data/icons/fdktest/16x16/text-x-generic.png",
                icon_png_text_16, icon_png_text_16_LEN);
    fixture_png("data/icons/fdktest/16x16/image-x-generic.png",
                icon_png_image_16, icon_png_image_16_LEN);
    fixture_png("data/icons/fdktest/16x16/run-symbolic.png",
                icon_png_exec_16, icon_png_exec_16_LEN);
    /* 48-px set. */
    fixture_png("data/icons/fdktest/48x48/folder.png",
                icon_png_folder_48, icon_png_folder_48_LEN);
    fixture_png("data/icons/fdktest/48x48/image-x-generic.png",
                icon_png_image_48, icon_png_image_48_LEN);
    /* The scalable dir serves any 16..64 request (audio). */
    fixture_png("data/icons/fdktest/32x32/audio-x-generic.png",
                icon_png_audio_16, icon_png_audio_16_LEN);
    /* scale!=1: present on disk, must never resolve. */
    fixture_png("data/icons/fdktest/64x64@2/video-x-generic.png",
                icon_png_video_48, icon_png_video_48_LEN);
    /* The threshold dir carries ONLY an empty-SVG decoy for the zip
     * name: found on disk (lookup offers it), refused at raster
     * time, and nothing else carries the name. */
    fixture_text("data/icons/fdktest/24x24/application-zip.svg",
                 "<svg xmlns=\"http://www.w3.org/2000/svg\"/>");
    /* The same-dir contest: folder.png (blue) vs folder.svg (green)
     * — the PNG must win. */
    fixture_text("data/icons/fdktest/16x16/folder.svg",
                 "<svg xmlns=\"http://www.w3.org/2000/svg\" "
                 "width=\"16\" height=\"16\" "
                 "viewBox=\"0 0 16 16\">"
                 "<rect x=\"0\" y=\"0\" width=\"16\" "
                 "height=\"16\" fill=\"#00FF00\"/></svg>");
    /* The rasterizable SVG in the scalable-only dir: solid red. */
    fixture_text("data/icons/fdktest/svgonly/image-x-preview.svg",
                 "<svg xmlns=\"http://www.w3.org/2000/svg\" "
                 "width=\"64\" height=\"64\" "
                 "viewBox=\"0 0 64 64\">"
                 "<path d=\"M0 0 H64 V64 H0 Z\" "
                 "fill=\"#FF0000\"/></svg>");
    /* CSS-class SVGs — the modern authoring shape (Papirus/Breeze/
     * Tela fill through <style> + class=). The vendored upstream
     * nanosvg parses these; the fixtures pin that the fills apply
     * AND the two properties-text shapes that used to overflow the
     * parser's heap (see the CSS-class group in test_surfaces). */
    fixture_text("data/icons/fdktest/svgonly/class-red.svg",
                 "<svg xmlns=\"http://www.w3.org/2000/svg\" "
                 "width=\"64\" height=\"64\" viewBox=\"0 0 64 64\">"
                 "<style type=\"text/css\">.s0{fill:#FF0000}</style>"
                 "<path class=\"s0\" d=\"M0 0 H64 V64 H0 Z\"/></svg>");
    /* The standard multiline rule (one declaration per line). The
     * properties text ends ';' + newline — the exact shape whose
     * empty final chunk read one byte past the heap block. */
    fixture_text("data/icons/fdktest/svgonly/class-newlines.svg",
                 "<svg xmlns=\"http://www.w3.org/2000/svg\" "
                 "width=\"64\" height=\"64\" viewBox=\"0 0 64 64\">"
                 "<style type=\"text/css\">\n"
                 ".s0 {\n  fill: #FF0000;\n}\n"
                 "</style>\n"
                 "<path class=\"s0\" d=\"M0 0 H64 V64 H0 Z\"/>\n"
                 "</svg>\n");
    /* A trailing comment after the last declaration (a colonless
     * final chunk — the other malformed-tail robustness shape). */
    fixture_text("data/icons/fdktest/svgonly/class-comment-tail.svg",
                 "<svg xmlns=\"http://www.w3.org/2000/svg\" "
                 "width=\"64\" height=\"64\" viewBox=\"0 0 64 64\">"
                 "<style type=\"text/css\">"
                 ".s0{fill:#FF0000; /* trailing comment */}"
                 "</style>"
                 "<path class=\"s0\" d=\"M0 0 H64 V64 H0 Z\"/></svg>");
    /* Two rules, one element: class="a b" applies both, the later
     * attribute class wins the fill. */
    fixture_text("data/icons/fdktest/svgonly/class-order.svg",
                 "<svg xmlns=\"http://www.w3.org/2000/svg\" "
                 "width=\"64\" height=\"64\" viewBox=\"0 0 64 64\">"
                 "<style type=\"text/css\">"
                 ".a{fill:#0000FF}.b{fill:#FF0000}"
                 "</style>"
                 "<path class=\"a b\" d=\"M0 0 H64 V64 H0 Z\"/></svg>");
    /* Selector list: .c,.d — the element carries only d. */
    fixture_text("data/icons/fdktest/svgonly/class-list.svg",
                 "<svg xmlns=\"http://www.w3.org/2000/svg\" "
                 "width=\"64\" height=\"64\" viewBox=\"0 0 64 64\">"
                 "<style type=\"text/css\">.c,.d{fill:#00FF00}</style>"
                 "<path class=\"d\" d=\"M0 0 H64 V64 H0 Z\"/></svg>");
    /* A class name with no matching rule: default fill, no crash. */
    fixture_text("data/icons/fdktest/svgonly/class-unknown.svg",
                 "<svg xmlns=\"http://www.w3.org/2000/svg\" "
                 "width=\"64\" height=\"64\" viewBox=\"0 0 64 64\">"
                 "<style type=\"text/css\">.zz{fill:#FF0000}</style>"
                 "<path class=\"s0\" d=\"M0 0 H64 V64 H0 Z\"/></svg>");
    /* Empty rule body: a no-op. */
    fixture_text("data/icons/fdktest/svgonly/class-empty.svg",
                 "<svg xmlns=\"http://www.w3.org/2000/svg\" "
                 "width=\"64\" height=\"64\" viewBox=\"0 0 64 64\">"
                 "<style type=\"text/css\">.s0{}</style>"
                 "<path class=\"s0\" d=\"M0 0 H64 V64 H0 Z\"/></svg>");
    /* Whitespace-only rule body — the second overflow shape. */
    fixture_text("data/icons/fdktest/svgonly/class-ws-only.svg",
                 "<svg xmlns=\"http://www.w3.org/2000/svg\" "
                 "width=\"64\" height=\"64\" viewBox=\"0 0 64 64\">"
                 "<style type=\"text/css\">.s0{   }</style>"
                 "<path class=\"s0\" d=\"M0 0 H64 V64 H0 Z\"/></svg>");
    /* The refusal pair: an EMPTY svg in the own theme, a valid PNG
     * in the parent — the refusal must expose the parent's icon. */
    fixture_text("data/icons/fdktest/48x48/shadow-test.svg",
                 "<svg xmlns=\"http://www.w3.org/2000/svg\"/>");
    /* The parent's 48-px archive chain member. */
    fixture_png("data/icons/fdkparent/48x48/package-x-generic.png",
                icon_png_archive_48, icon_png_archive_48_LEN);
    fixture_png("data/icons/fdkparent/48x48/shadow-test.png",
                icon_png_archive_48, icon_png_archive_48_LEN);
    /* hicolor's terminal 16-px text icon. */
    fixture_png("data/icons/hicolor/16x16/text-x-generic.png",
                icon_png_text_16, icon_png_text_16_LEN);
    /* The pixmaps flat fallback (under the XDG_DATA_DIRS entry the
     * engine derives it from). */
    fixture_png("datadirs/pixmaps/fdk-legacy.png",
                icon_png_home_16, icon_png_home_16_LEN);
}

