/* ---- 1. name detection ---------------------------------------------- */

static void test_current_name(void) {
    env_point_at_fixture();

    /* The explicit override wins. */
    setenv("FDK_ICON_THEME", "fdktest", 1);
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdktest") == 0,
          "env override detected");

    /* A hostile override is rejected and detection falls through. */
    setenv("FDK_ICON_THEME", "../../etc", 1);
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "hicolor") == 0,
          "hostile env name rejected -> default");

    /* The classic icon-theme file. */
    unsetenv("FDK_ICON_THEME");
    fixture_text("config/icon-theme", "fdktest\n");
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdktest") == 0,
          "icon-theme file detected");

    /* GTK settings.ini (quoted value form). */
    {
        char buf[600];
        snprintf(buf, sizeof(buf), "%s/config/icon-theme", g_root);
        remove(buf);
    }
    fixture_dir("config/gtk-3.0");
    fixture_text("config/gtk-3.0/settings.ini",
                 "[Settings]\ngtk-icon-theme-name=\"fdktest\"\n");
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdktest") == 0,
          "gtk-3.0 settings.ini detected (quoted)");

    /* kdeglobals. */
    {
        char buf[600];
        snprintf(buf, sizeof(buf), "%s/config/gtk-3.0/settings.ini",
                 g_root);
        remove(buf);
    }
    fixture_text("config/kdeglobals",
                 "[Icons]\nTheme=fdktest\n");
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdktest") == 0,
          "kdeglobals [Icons] Theme detected");

    /* ---- 1.5.3 channels ---- */

    /* XFCE xfconf xsettings.xml (nested property, the real layout
     * xfsettingsd persists). Beats kdeglobals (channel 5 > 7). */
    fixture_dir("config/xfce4/xfconf/xfce-perchannel-xml");
    fixture_text("config/xfce4/xfconf/xfce-perchannel-xml/xsettings.xml",
                 "<channel name=\"xsettings\" version=\"1\">\n"
                 "  <property name=\"Net\" type=\"empty\">\n"
                 "    <property name=\"IconThemeName\" type=\"string\" "
                 "value=\"fdktest\"/>\n"
                 "  </property>\n"
                 "</channel>\n");
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdktest") == 0,
          "xfconf xsettings.xml IconThemeName detected (beats kdeglobals)");

    /* xfconf value with an XML entity: unescaped before use. */
    fixture_text("config/xfce4/xfconf/xfce-perchannel-xml/xsettings.xml",
                 "<channel name=\"xsettings\" version=\"1\">\n"
                 "  <property name=\"IconThemeName\" type=\"string\" "
                 "value=\"A&amp;B\"/>\n"
                 "</channel>\n");
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "A&B") == 0,
          "xfconf XML entity unescaped in the value");

    /* User GTK ini beats xfconf (channel 3 > 4 — GTK's own fallback
     * order; the desktop's GTK apps would see the same winner). */
    fixture_dir("config/gtk-3.0");
    fixture_text("config/gtk-3.0/settings.ini",
                 "[Settings]\ngtk-icon-theme-name=fdkparent\n");
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdkparent") == 0,
          "user gtk ini beats xfconf");
    {
        char buf[600];
        snprintf(buf, sizeof(buf), "%s/config/gtk-3.0/settings.ini",
                 g_root);
        remove(buf);
    }

    /* System GTK settings.ini (XDG_CONFIG_DIRS root): serves when
     * every user channel is silent. */
    fixture_dir("sysxdg/gtk-3.0");
    fixture_text("sysxdg/gtk-3.0/settings.ini",
                 "[Settings]\ngtk-icon-theme-name=fdklegacy\n");
    {
        char buf[600];
        snprintf(buf, sizeof(buf), "%s/config/kdeglobals", g_root);
        remove(buf);
    }
    {
        char buf[600];
        snprintf(buf, sizeof(buf),
                 "%s/config/xfce4/xfconf/xfce-perchannel-xml/"
                 "xsettings.xml", g_root);
        remove(buf);
    }
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdklegacy") == 0,
          "system gtk settings.ini (XDG_CONFIG_DIRS) detected");

    /* The system channel sits BELOW every USER channel: the user's
     * gtk-4.0 ini wins when both exist. */
    fixture_dir("config/gtk-4.0");
    fixture_text("config/gtk-4.0/settings.ini",
                 "[Settings]\ngtk-icon-theme-name=fdktest\n");
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdktest") == 0,
          "user gtk-4.0 ini beats the system gtk-3.0 ini");
    {
        char buf[600];
        snprintf(buf, sizeof(buf), "%s/config/gtk-4.0/settings.ini",
                 g_root);
        remove(buf);
    }

    {
        char buf[600];
        snprintf(buf, sizeof(buf), "%s/sysxdg/gtk-3.0/settings.ini",
                 g_root);
        remove(buf);
    }
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "hicolor") == 0,
          "no statement anywhere -> hicolor");

    /* The system-default channel: <base>/default/index.theme
     * Inherits= — the channel stock GNOME/XFCE publish when no
     * user config exists (gsettings itself is D-Bus, out of
     * policy reach). Lives in the XDG_DATA_DIRS base here. */
    fixture_text("datadirs/icons/default/index.theme",
                 "[Icon Theme]\nName=Default\nInherits=fdkparent\n");
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdkparent") == 0,
          "system default/index.theme Inherits= detected");
    /* A comma list serves its first entry only. */
    fixture_text("datadirs/icons/default/index.theme",
                 "[Icon Theme]\nName=Default\nInherits=fdkparent,other\n");
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdkparent") == 0,
          "default channel takes the first Inherits entry");
    {
        char buf[600];
        snprintf(buf, sizeof(buf), "%s/datadirs/icons/default/"
                 "index.theme", g_root);
        remove(buf);
    }
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "hicolor") == 0,
          "default channel removed -> hicolor again");

    /* Detection re-reads after reset (no stale name across swaps). */
    setenv("FDK_ICON_THEME", "fdkparent", 1);
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdkparent") == 0,
          "name re-detected after reset");
    printf("[ok] icon theme: name detection chain "
           "(env > XSETTINGS > gtk ini > xfconf > kdeglobals > "
           "icon-theme file > system gtk ini > default/index.theme > "
           "hicolor; hostile names rejected)\n");
}

/* ---- 2. lookup ------------------------------------------------------- */

static void test_lookup(void) {
    env_point_at_fixture();
    setenv("FDK_ICON_THEME", "fdktest", 1);
    fdk__icon_theme_reset();

    /* Exact size, own theme. */
    char *p = fdk__icon_theme_lookup("folder", 16);
    CHECK(p != NULL && strstr(p, "fdktest/16x16/folder.png") != NULL,
          "exact-size own-theme hit");
    fdk_free(p);

    /* 48 serves from the 48 dir. */
    p = fdk__icon_theme_lookup("folder", 48);
    CHECK(p != NULL && strstr(p, "fdktest/48x48/folder.png") != NULL,
          "48-px hit");
    fdk_free(p);

    /* Scalable range: 20 fits 16..64 -> the 32x32 file. */
    p = fdk__icon_theme_lookup("audio-x-generic", 20);
    CHECK(p != NULL && strstr(p, "32x32/audio-x-generic.png") != NULL,
          "scalable dir serves in-range size");
    fdk_free(p);

    /* Relaxed pass: 64 is outside the theme's every dir for
     * image-x-generic except... 48 is closest -> the 48 file. */
    p = fdk__icon_theme_lookup("image-x-generic", 64);
    CHECK(p != NULL && strstr(p, "48x48/image-x-generic.png") != NULL,
          "relaxed closest-size fallback");
    fdk_free(p);

    /* Inheritance: package-x-generic misses fdktest entirely
     * -> the parent's own file. */
    p = fdk__icon_theme_lookup("package-x-generic", 48);
    CHECK(p != NULL && strstr(p, "fdkparent/48x48") != NULL,
          "inherited hit from parent theme");
    fdk_free(p);

    /* The hicolor terminal. */
    p = fdk__icon_theme_lookup("nothing-anywhere", 16);
    CHECK(p == NULL, "unknown name misses everywhere");
    /* Negative result cached: still NULL, no filesystem churn. */
    p = fdk__icon_theme_lookup("nothing-anywhere", 16);
    CHECK(p == NULL, "negative cache hit");

    /* SVG is now a first-class candidate: the file exists, the
     * LOOKUP offers it (filesystem truth — whether it RASTERS is
     * the surface layer's business, see test_surfaces). */
    p = fdk__icon_theme_lookup("application-zip", 24);
    CHECK(p != NULL && strstr(p, "24x24/application-zip.svg") != NULL,
          "SVG candidate offered by lookup");
    fdk_free(p);

    /* The rasterizable SVG in the scalable dir: any size in its
     * 8..512 range is distance-0. */
    p = fdk__icon_theme_lookup("image-x-preview", 48);
    CHECK(p != NULL && strstr(p, "svgonly/image-x-preview.svg") != NULL,
          "scalable-dir SVG resolves at any in-range size");
    fdk_free(p);

    /* Same-directory contest: folder.png beats folder.svg. */
    p = fdk__icon_theme_lookup("folder", 16);
    CHECK(p != NULL && strstr(p, "16x16/folder.png") != NULL,
          "PNG preferred over SVG in the same directory");
    fdk_free(p);

    /* scale != 1 directories are skipped. */
    p = fdk__icon_theme_lookup("video-x-generic", 64);
    CHECK(p == NULL, "scale!=1 dir skipped");

    /* Threshold: 22 within 24+-2 -> the dir would serve, but the
     * only file in it is the empty application-zip.svg (a different
     * name) -> archive-x-generic misses honestly. */
    p = fdk__icon_theme_lookup("archive-x-generic", 22);
    CHECK(p == NULL, "threshold dir without the name misses");

    /* The pixmaps flat fallback. */
    p = fdk__icon_theme_lookup("fdk-legacy", 16);
    CHECK(p != NULL && strstr(p, "pixmaps/fdk-legacy.png") != NULL,
          "pixmaps flat fallback");
    fdk_free(p);

    /* Hostile icon names never reach the filesystem. */
    CHECK(fdk__icon_theme_lookup("../..", 16) == NULL,
          "hostile icon name rejected");
    CHECK(fdk__icon_theme_lookup("a/b", 16) == NULL,
          "icon name with slash rejected");

    printf("[ok] icon theme: lookup (exact, scalable, relaxed, "
           "inheritance, hicolor terminal, SVG candidates, PNG-first, "
           "scale skips, pixmaps, negative cache, path safety)\n");
}

/* ---- 3. reset drops the caches --------------------------------------- */

static void test_reset(void) {
    setenv("FDK_ICON_THEME", "fdktest", 1);
    fdk__icon_theme_reset();
    char *p = fdk__icon_theme_lookup("folder", 16);
    CHECK(p != NULL, "pre-reset lookup");
    fdk_free(p);

    /* Break the fixture, reset, and confirm the miss is fresh. The
     * 16 PNG, the 16 SVG (the same-dir runner-up), and the 48 PNG
     * must all go: the relaxed pass would otherwise LEGITIMATELY
     * serve the 48-px icon at distance 32, and the SVG would win
     * its directory outright once the PNG is gone. */
    char buf[600];
    snprintf(buf, sizeof(buf), "%s/data/icons/fdktest/16x16/folder.png",
             g_root);
    remove(buf);
    snprintf(buf, sizeof(buf), "%s/data/icons/fdktest/16x16/folder.svg",
             g_root);
    remove(buf);
    snprintf(buf, sizeof(buf), "%s/data/icons/fdktest/48x48/folder.png",
             g_root);
    remove(buf);
    fdk__icon_theme_reset();
    p = fdk__icon_theme_lookup("folder", 16);
    CHECK(p == NULL, "reset drops positive cache (miss is fresh)");
    fdk_free(p);

    /* Negative cache drops too: restore + reset -> hit again. */
    fixture_png("data/icons/fdktest/16x16/folder.png",
                icon_png_folder_16, icon_png_folder_16_LEN);
    fixture_png("data/icons/fdktest/48x48/folder.png",
                icon_png_folder_48, icon_png_folder_48_LEN);
    fixture_text("data/icons/fdktest/16x16/folder.svg",
                 "<svg xmlns=\"http://www.w3.org/2000/svg\" "
                 "width=\"16\" height=\"16\" "
                 "viewBox=\"0 0 16 16\">"
                 "<rect x=\"0\" y=\"0\" width=\"16\" "
                 "height=\"16\" fill=\"#00FF00\"/></svg>");
    fdk__icon_theme_reset();
    p = fdk__icon_theme_lookup("folder", 16);
    CHECK(p != NULL, "reset drops negative cache");
    fdk_free(p);
    printf("[ok] icon theme: reset drops positive and negative caches\n");
}

/* ---- 4. surfaces + symbolic tint ------------------------------------- */

/* A full-bleed class-fixture icon checked by center color at 48 px:
 * the fixture paths cover the whole cell, so the fill color is the
 * identity. Shared by the CSS-class regression group below. */
static void check_class_icon(const char *name, fdk_u32 r, fdk_u32 g,
                              fdk_u32 b, const char *what) {
    fdk_surface *s = fdk__icon_theme_surface(name, 48);
    CHECK(s != NULL, what);
    if (s == NULL) {
        return;
    }
    fdk_surface_info info;
    if (fdk_surface_get_info(s, &info) != FDK_OK ||
        info.width != 48 || info.height != 48) {
        CHECK(false, "class icon rasterized at the requested size");
        return;
    }
    fdk_u32 px = info.pixels[(size_t)24 * (size_t)info.stride + 24];
    CHECK((px >> 24 & 0xFFu) == 0xFFu &&
          (px >> 16 & 0xFFu) == r &&
          (px >> 8 & 0xFFu) == g &&
          (px & 0xFFu) == b,
          what);
}

static void test_surfaces(void) {
    setenv("FDK_ICON_THEME", "fdktest", 1);
    fdk__icon_theme_reset();

    /* Decode + identity: the folder icon is pure blue. */
    fdk_surface *s = fdk__icon_theme_surface("folder", 16);
    CHECK(s != NULL, "surface decodes");
    fdk_surface_info info;
    CHECK(fdk_surface_get_info(s, &info) == FDK_OK, "surface info");
    CHECK(info.width == 16 && info.height == 16, "16-px icon decoded");
    fdk_u32 px = info.pixels[0];
    CHECK((px >> 24 & 0xFFu) == 0xFFu && (px >> 16 & 0xFFu) == 0x00u &&
          (px >> 8 & 0xFFu) == 0x00u && (px & 0xFFu) == 0xFFu,
          "folder icon is solid blue (identity by color)");

    /* The borrow contract: same pointer for the same (name,size). */
    fdk_surface *again = fdk__icon_theme_surface("folder", 16);
    CHECK(again == s, "surface cache returns the same borrow");

    /* Different size, different surface. */
    fdk_surface *big = fdk__icon_theme_surface("folder", 48);
    CHECK(big != NULL && big != s, "48-px is its own surface");
    CHECK(fdk_surface_get_info(big, &info) == FDK_OK &&
          info.width == 48, "48-px decoded");

    /* The symbolic tint: run-symbolic's magenta is replaced by the
     * theme's text ink, alpha preserved. */
    fdk_surface *sym = fdk__icon_theme_surface("run-symbolic", 16);
    CHECK(sym != NULL, "symbolic surface decodes");
    CHECK(fdk_surface_get_info(sym, &info) == FDK_OK, "symbolic info");
    fdk_color ink = fdk_theme_get_color(NULL, FDK_TK_TEXT);
    px = info.pixels[0];
    fdk_u32 want_r = (fdk_u32)(ink.r * 255.0f + 0.5f);
    fdk_u32 want_g = (fdk_u32)(ink.g * 255.0f + 0.5f);
    fdk_u32 want_b = (fdk_u32)(ink.b * 255.0f + 0.5f);
    CHECK((px >> 24 & 0xFFu) == 0xFFu &&
          (px >> 16 & 0xFFu) == want_r && (px >> 8 & 0xFFu) == want_g &&
          (px & 0xFFu) == want_b,
          "symbolic icon tinted with the theme's text ink");

    /* The chain resolver: first decodable entry wins; a fully
     * missing chain misses. */
    static const char *const chain_hit[] = { "no-such-icon",
                                             "folder", NULL };
    CHECK(fdk__icon_theme_surface_chain(chain_hit, 16) == s,
          "chain resolver skips misses to the first hit");
    static const char *const chain_miss[] = { "no-such-icon", NULL };
    CHECK(fdk__icon_theme_surface_chain(chain_miss, 16) == NULL,
          "all-miss chain returns NULL");

    /* SVG rasterization: the scalable dir's solid-RED icon, decoded
     * at the REQUESTED size with the requested geometry, identity
     * by color. This is the pixel-level proof the nanosvg path
     * actually draws. */
    fdk_surface *svg = fdk__icon_theme_surface("image-x-preview", 48);
    CHECK(svg != NULL, "SVG surface rasterizes");
    if (svg != NULL) {
        CHECK(fdk_surface_get_info(svg, &info) == FDK_OK &&
              info.width == 48 && info.height == 48,
              "SVG rasterized at the requested size");
        px = info.pixels[0];
        CHECK((px >> 24 & 0xFFu) == 0xFFu &&
              (px >> 16 & 0xFFu) == 0xFFu &&
              (px >> 8 & 0xFFu) == 0x00u &&
              (px & 0xFFu) == 0x00u,
              "SVG icon is solid red (identity by color)");
        px = info.pixels[(size_t)23 * (size_t)info.stride + 23];
        CHECK((px >> 24 & 0xFFu) == 0xFFu &&
              (px >> 16 & 0xFFu) == 0xFFu,
              "SVG center pixel red too (full coverage)");
    }
    /* A different requested size rasterizes at THAT size. */
    fdk_surface *svg24 = fdk__icon_theme_surface("image-x-preview", 24);
    CHECK(svg24 != NULL && svg24 != svg &&
          fdk_surface_get_info(svg24, &info) == FDK_OK &&
          info.width == 24,
          "SVG rasters per requested size (24 is its own surface)");

    /* ---- the PUBLIC wrapper: fdk_icon_theme_surface (1.1.0) ------
     * The add-on surface (notifyd's icon path, the future tray
     * host's): an OWNED clone, never the cache's own pointer, with
     * the pixels arriving verbatim (identity by color on the solid
     * fixtures) and the miss contract falling to NULL. */
    {
        fdk_surface *pub = fdk_icon_theme_surface("folder", 16);
        CHECK(pub != NULL, "public icon lookup decodes");
        if (pub != NULL) {
            CHECK(pub != s, "public lookup is an owned clone, not the cache");
            CHECK(fdk_surface_get_info(pub, &info) == FDK_OK &&
                  info.width == 16 && info.height == 16,
                  "public clone keeps the geometry");
            fdk_u32 ppx = info.pixels[0];
            CHECK((ppx >> 24 & 0xFFu) == 0xFFu &&
                  (ppx >> 16 & 0xFFu) == 0x00u &&
                  (ppx >> 8 & 0xFFu) == 0x00u &&
                  (ppx & 0xFFu) == 0xFFu,
                  "public clone pixels verbatim (solid blue identity)");
            fdk_surface_destroy(pub);
        }
        CHECK(fdk_icon_theme_surface("no-such-icon-anywhere", 16) == NULL,
              "public lookup misses to NULL");
        CHECK(fdk_icon_theme_surface(NULL, 16) == NULL &&
              fdk_icon_theme_surface("", 16) == NULL &&
              fdk_icon_theme_surface("folder", 0) == NULL &&
              fdk_icon_theme_surface("folder", 5000) == NULL,
              "public lookup rejects NULL/empty names and bad sizes");
    }

    /* ---- CSS-class SVGs: the modern-theme authoring shape -------
     * The vendored upstream nanosvg parses <style> blocks and
     * simple class selectors — the shape Papirus/Breeze/Tela themes
     * fill their icons through. The group pins that class fills
     * APPLY and holds the two properties-text shapes that used to
     * read one byte past the strndup'ed rule text (a
     * heap-buffer-overflow under ASAN — the crash that aborted
     * every file-dialog open on a class-using desktop theme): a
     * declaration block ending ';' + trailing whitespace (the
     * standard multiline rule) and a whitespace-only block. Both
     * shapes sent the name scanner to end, and the old right-trim
     * dereferenced *end one byte past the NUL. */
    check_class_icon("class-red", 0xFF, 0x00, 0x00,
                     "class-styled SVG: the fill applies (solid red)");
    check_class_icon("class-newlines", 0xFF, 0x00, 0x00,
                     "multiline class CSS rasterizes red (the "
                     "trailing-newline overflow shape)");
    check_class_icon("class-comment-tail", 0xFF, 0x00, 0x00,
                     "trailing-comment class CSS rasterizes red (the "
                     "colonless-tail shape)");
    check_class_icon("class-order", 0xFF, 0x00, 0x00,
                     "multi-class: both rules apply, attribute order "
                     "wins the fill (red)");
    check_class_icon("class-list", 0x00, 0xFF, 0x00,
                     "selector-list rule applies to each member "
                     "(solid green)");
    check_class_icon("class-unknown", 0x00, 0x00, 0x00,
                     "unmatched class keeps the default black fill");
    check_class_icon("class-empty", 0x00, 0x00, 0x00,
                     "empty rule body is a no-op (default fill)");
    check_class_icon("class-ws-only", 0x00, 0x00, 0x00,
                     "whitespace-only rule body survives (the second "
                     "overflow shape, default fill)");

    /* The same-dir contest at the SURFACE level: folder.svg (green)
     * lost to folder.png (blue) — already proven above by the blue
     * identity; the lookup-level check pins the mechanism. */

    /* THE SHADOWING REGRESSION: fdktest/48x48/shadow-test.svg is
     * EMPTY (exists, will never raster). The refusal set must skip
     * it and the chain must fall through to fdkparent's valid PNG —
     * the exact bug class where one broken asset in the
     * highest-priority theme pins the procedural glyph forever. */
    fdk_surface *shadow = fdk__icon_theme_surface("shadow-test", 48);
    CHECK(shadow != NULL, "empty-SVG refusal falls through to parent");
    if (shadow != NULL) {
        /* Identity: same pixels as a direct decode of the parent's
         * PNG (byte-for-byte the same fixture asset). */
        char pathbuf[600];
        snprintf(pathbuf, sizeof(pathbuf),
                 "%s/data/icons/fdkparent/48x48/shadow-test.png", g_root);
        fdk_surface *ref = NULL;
        CHECK(fdk_surface_create_from_image(pathbuf, &ref) == FDK_OK,
              "reference decode of the parent PNG");
        if (ref != NULL) {
            fdk_surface_info ri, si;
            bool same = fdk_surface_get_info(ref, &ri) == FDK_OK &&
                        fdk_surface_get_info(shadow, &si) == FDK_OK &&
                        ri.width == si.width &&
                        ri.height == si.height;
            if (same) {
                for (fdk_i32 y = 0; y < si.height && same; y++) {
                    const fdk_u32 *ra = ri.pixels + (size_t)y * (size_t)ri.stride;
                    const fdk_u32 *sa = si.pixels + (size_t)y * (size_t)si.stride;
                    for (fdk_i32 x = 0; x < si.width; x++) {
                        if (ra[x] != sa[x]) {
                            same = false;
                            break;
                        }
                    }
                }
            }
            CHECK(same, "refused-svg chain serves the parent's PNG "
                  "(pixel identity)");
            fdk_surface_destroy(ref);
        }
    }
    /* The refusal is durable and cache-coherent: the post-refusal
     * lookup skips the empty SVG and returns the parent's PNG. */
    char *sp = fdk__icon_theme_lookup("shadow-test", 48);
    CHECK(sp != NULL && strstr(sp, "fdkparent/48x48/shadow-test.png") != NULL,
          "lookup after refusal skips the empty SVG");
    fdk_free(sp);

    /* The empty-SVG name with NO valid fallback anywhere: honest
     * miss at the surface level (refused, nothing left to serve). */
    CHECK(fdk__icon_theme_surface("application-zip", 24) == NULL,
          "undrawable SVG with no fallback is a surface-level miss");

    /* Reset destroys the surfaces — proven by CONTENT, not pointer
     * identity. Pointer inequality after a free is an allocator
     * implementation detail: under ASan (the default build) the
     * quarantine guarantees a fresh address, but the Void Linux
     * packaging pipeline builds FDK_SANITIZE=0 and plain glibc
     * legitimately reuses the just-freed chunk for the same-size
     * re-decode, which flaked the old `fresh != s` assert exactly
     * there. The behavioral contract of reset is that the next
     * lookup re-reads the asset from disk: rewrite the backing
     * file to a different solid color and require the fresh decode
     * to show the NEW pixels (a surviving cache would still show
     * the original blue). */
    fixture_png("data/icons/fdktest/16x16/folder.png",
                icon_png_image_16, icon_png_image_16_LEN);
    fdk__icon_theme_reset();
    fdk_surface *fresh = fdk__icon_theme_surface("folder", 16);
    int fresh_green = 0;
    if (fresh != NULL && fdk_surface_get_info(fresh, &info) == FDK_OK) {
        px = info.pixels[0];
        fresh_green = (px >> 24 & 0xFFu) == 0xFFu &&
                      (px >> 16 & 0xFFu) == 0x00u &&
                      (px >> 8 & 0xFFu) == 0xFFu &&
                      (px & 0xFFu) == 0x00u;
    }
    CHECK(fresh != NULL && fresh_green,
          "reset drops decoded surfaces (fresh decode shows the "
          "rewritten asset, not the cached blue)");
    printf("[ok] icon theme: surfaces (decode, borrow identity, "
           "symbolic tint pixels, chain resolution, SVG raster "
           "identity, CSS-class shapes incl. the heap-overflow "
           "regressions, refusal/shadowing, reset)\n");
}

/* ---- 5. classification ----------------------------------------------- */

static void test_classification(void) {
    /* Directories are folders, case does not matter, and the
     * executable bit splits extension-less files. */
    CHECK(fdk__icon_chain_for_entry("/x", "anything", true) != NULL &&
          strcmp(fdk__icon_chain_for_entry("/x", "anything", true)[0],
                 "folder") == 0,
          "directory classifies as folder");

    const char *const *c =
        fdk__icon_chain_for_entry("/x", "photo.PNG", false);
    CHECK(c != NULL && strcmp(c[0], "image-x-generic") == 0,
          "extension match is case-insensitive");

    c = fdk__icon_chain_for_entry("/x", "archive.tar.gz", false);
    CHECK(c != NULL && strcmp(c[0], "application-x-compressed-tar") == 0,
          "compound extension classified");

    c = fdk__icon_chain_for_entry("/x", "main.c", false);
    CHECK(c != NULL && strcmp(c[0], "text-x-csrc") == 0,
          "source file classified");

    c = fdk__icon_chain_for_name("song.opus");
    CHECK(c != NULL && strcmp(c[0], "audio-x-generic") == 0,
          "audio classified");

    c = fdk__icon_chain_for_name("movie.mkv");
    CHECK(c != NULL && strcmp(c[0], "video-x-generic") == 0,
          "video classified");

    /* Extension-less files: the executable bit decides. */
    char dir[700];
    snprintf(dir, sizeof(dir), "%s/cls", g_root);
    mkdir(dir, 0755);
    char prog[768], plain[768];
    snprintf(prog, sizeof(prog), "%s/runme", dir);
    snprintf(plain, sizeof(plain), "%s/plainfile", dir);
    write_file(prog, "#!/bin/sh\n", 10);
    write_file(plain, "data", 4);
    chmod(prog, 0755);

    c = fdk__icon_chain_for_entry(dir, "runme", false);
    CHECK(c != NULL && strcmp(c[0], "application-x-executable") == 0,
          "extension-less + exec bit -> executable chain");
    c = fdk__icon_chain_for_entry(dir, "plainfile", false);
    CHECK(c != NULL && strcmp(c[0], "text-x-generic") == 0,
          "extension-less plain file -> text chain");

    /* Unknown extensions fall to the exec-bit split too. */
    c = fdk__icon_chain_for_entry(dir, "data.zzz", false);
    CHECK(c != NULL && strcmp(c[0], "text-x-generic") == 0,
          "unknown extension -> exec-bit split -> text");

    /* Every chain is NULL-terminated (the resolver walks safely). */
    for (size_t i = 0; i < 32; i++) {
        char name[32];
        snprintf(name, sizeof(name), "f%zu.zzz", i);
        const char *const *ch = fdk__icon_chain_for_entry(dir, name,
                                                          false);
        CHECK(ch != NULL && ch[0] != NULL, "chains always non-empty");
    }

    /* The place chains carry the symbolic-first desktop norm. */
    CHECK(strcmp(fdk__icon_chain_place(FDK_ICON_PLACE_HOME)[0],
                 "user-home-symbolic") == 0,
          "home place chain is symbolic-first");
    CHECK(strcmp(fdk__icon_chain_place(FDK_ICON_PLACE_DRIVE)[0],
                 "drive-harddisk-symbolic") == 0,
          "drive place chain is symbolic-first");

    remove(prog);
    remove(plain);
    remove(dir);
    printf("[ok] icon theme: classification (case-insensitive exts, "
           "compound exts, exec-bit split, place chains)\n");
}

int main(void) {
    build_fixture();
    test_current_name();
    test_lookup();
    test_reset();
    test_surfaces();
    test_classification();
    drop_fixture();
    if (failures == 0) {
        printf("all icon-theme tests passed\n");
        return 0;
    }
    fprintf(stderr, "%d icon-theme test failure%s\n", failures,
            failures == 1 ? "" : "s");
    return 1;
}
